&lt;/div&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-42z69zz85zx9z84zz79zvz66zz71z4yz65zz67znhz79zc70z90zz79z8cz81zjibz77z9gebz89zz75zz71zz73zpg7v7dn&quot;&gt;5+ years leading global IT support or service operations&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-42z69zz85zx9z84zz79zvz66zz71z4yz65zz67znhz79zc70z90zz79z8cz81zjibz77z9gebz89zz75zz71zz73zpg7v7dn&quot;&gt;Experience managing vendor-governed service models&lt;/span&gt;&lt;/li&gt;
