&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86zhnz122zz81z6z80z0y1z83zz85zpz81zz87ztc3mlz69zz74zz87zq2z69ztrz65z0&quot;&gt;9&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z8h00wiph6z86zz86z7z89z3z66zz68z0z82zxz68zz67z1z74z8z79z7z70zz67zcyz80z&quot;&gt;+ years of professional software development experience&lt;/span&gt;&lt;/li&gt;
