&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz82zfwz66zwgz76zz77zz88zoz67zz83z1z87zpoz80zz84zsz83zx8z67zz66zz84zz76zz74z7z83zz72zz86z&quot;&gt;Proven track record of defining technical roadmaps for the team&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qoxuz87z1z75zz66z3bz71zz84zz67z7r8z79z44rz77zz71z6z79zz76zsz73z0ivdz78zz77zq&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
