&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovvunz66z4z78z1dz79zz78zpz90z2z69z2z77z1gf3naz73zz122ze6j5sjz73z&quot;&gt;Lead accurate, accountable forecasting and uphold a high bar for deal validity&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;thread-191398886564973542394386 attrcomment attrcommentfirst thread-191398886564973542394386-first author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovvunz66z4z78z1dz79zz78zpz90z2z69z2z77z1gf3naz73zz122ze6j5sjz73z&quot;&gt;&lt;span class=&quot;comment-extra-inner-span&quot;&gt;Coach reps on value-based selling, focusing on customer problems, impact, and differentiation&lt;/span&gt;&lt;/span&gt; &lt;span class=&quot;thread-191398886564973542394386 attrcomment author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zbserz76zbpe7snpz73zo7z78z5z74zz79zz71zz81zp70z79zz66zt8m h-lparen&quot;&gt;&lt;span class=&quot;comment-extra-inner-span&quot;&gt;(experience&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;thread-191398886564973542394386 attrcomment author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zbserz76zbpe7snpz73zo7z78z5z74zz79zz71zz81zp70z79zz66zt8m&quot;&gt;&lt;span class=&quot;comment-extra-inner-span&quot;&gt; with Command of the Message or other frameworks preferred)&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovvunz66z4z78z1dz79zz78zpz90z2z69z2z77z1gf3naz73zz122ze6j5sjz73z&quot;&gt;Drive transformation by refining ICP, messaging, and GTM for evolving products&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovvunz66z4z78z1dz79zz78zpz90z2z69z2z77z1gf3naz73zz122ze6j5sjz73z h-lparen&quot;&gt;(e.g.,&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovvunz66z4z78z1dz79zz78zpz90z2z69z2z77z1gf3naz73zz122ze6j5sjz73z&quot;&gt; Dash)&lt;/span&gt;&lt;/li&gt;
